package local.nuvio.catalog;
import android.content.Context;
import android.util.Log;
import android.icu.text.Transliterator;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;

public class CatalogServer {
 static final String ADDON="local.nuvio.curated.zh", IMG="https://images.tmdb.org/t/p/";
 final Context ctx;final File root,cache;final JSONArray config;final Map<String,JSONObject> specs=new HashMap<>();final String key;
 final ExecutorService requests=Executors.newFixedThreadPool(20), translations=Executors.newFixedThreadPool(4);
 final Semaphore network=new Semaphore(8);final ConcurrentHashMap<String,Object> locks=new ConcurrentHashMap<>();
 final Map<String,JSONObject> artItems=new HashMap<>();final Map<String,Long> artTimes=new HashMap<>();
 ServerSocket listener;volatile boolean running=true;
 public CatalogServer(Context c)throws Exception{ctx=c;root=c.getFilesDir();cache=new File(root,"cache");cache.mkdirs();key=read(new File(root,"tmdb-key")).trim();config=new JSONArray(read(new File(root,"catalogs.json")));for(int i=0;i<config.length();i++){JSONObject s=config.getJSONObject(i);specs.put(s.getString("id"),s);}}
 static String read(File f)throws Exception{return new String(Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8);}
 static String hash(String s)throws Exception{byte[] b=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder r=new StringBuilder();for(byte v:b)r.append(String.format("%02x",v&255));return r.toString();}
 static JSONObject copy(JSONObject x)throws Exception{return new JSONObject(x.toString());}
 static JSONObject obj(Object... kv)throws Exception{JSONObject o=new JSONObject();for(int i=0;i<kv.length;i+=2)o.put((String)kv[i],kv[i+1]);return o;}
 static JSONArray arr(JSONObject o,String k){JSONArray a=o.optJSONArray(k);return a==null?new JSONArray():a;}
 static String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
 byte[] download(String url)throws Exception{if(!url.startsWith("https://"))throw new IOException("HTTPS required");network.acquire();try{HttpURLConnection h=(HttpURLConnection)new URL(url).openConnection();h.setConnectTimeout(15000);h.setReadTimeout(22000);h.setRequestProperty("User-Agent","NuvioTVCatalog/1.0");try{if(h.getResponseCode()!=200)throw new IOException("Upstream HTTP "+h.getResponseCode());try(InputStream in=h.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}finally{h.disconnect();}}finally{network.release();}}
 void atomic(File f,byte[] b)throws Exception{File t=new File(f.getPath()+"."+Thread.currentThread().getId()+".tmp");Files.write(t.toPath(),b);Files.move(t.toPath(),f.toPath(),StandardCopyOption.REPLACE_EXISTING);}
 JSONObject cached(String url,long ttl)throws Exception{File f=new File(cache,"java-"+hash(url)+".json");synchronized(locks.computeIfAbsent(url,k->new Object())){if(f.exists()&&System.currentTimeMillis()-f.lastModified()<ttl)return new JSONObject(read(f));try{byte[] bytes=download(url);JSONObject data=new JSONObject(new String(bytes,StandardCharsets.UTF_8));if(data.has("status_code")&&!data.optBoolean("success",true))throw new IOException("TMDB rejected request");atomic(f,bytes);return data;}catch(Exception e){if(f.exists())return new JSONObject(read(f));throw e;}}}
 JSONObject fetch(String path,JSONObject params)throws Exception{JSONObject p=copy(params);if(!p.has("language"))p.put("language","zh-CN");TreeMap<String,String> sorted=new TreeMap<>();Iterator<String> it=p.keys();while(it.hasNext()){String k=it.next();sorted.put(k,p.getString(k));}StringBuilder url=new StringBuilder("https://api.tmdb.org/3/"+path+"?api_key="+enc(key));for(Map.Entry<String,String> e:sorted.entrySet())url.append('&').append(enc(e.getKey())).append('=').append(enc(e.getValue()));return cached(url.toString(),21600000L);}
 JSONObject fetch(String path)throws Exception{return fetch(path,new JSONObject());}
 static boolean cjk(String s){return s!=null&&s.matches("(?s).*[\\u4e00-\\u9fff].*");}
 static String simplified(String s){try{return Transliterator.getInstance("Traditional-Simplified").transliterate(s);}catch(Exception e){return s;}}
 JSONObject chinese(JSONObject original,String media)throws Exception{JSONObject d=copy(original);String tk=media.equals("movie")?"title":"name";if(cjk(d.optString(tk))&&cjk(d.optString("overview")))return d;String base=media+"/"+d.get("id");List<JSONObject> ts=new ArrayList<>();try{JSONArray a=arr(fetch(base+"/translations"),"translations");for(int i=0;i<a.length();i++){JSONObject t=a.getJSONObject(i);if(t.optString("iso_639_1").equals("zh"))ts.add(t);}List<String> order=Arrays.asList("CN","SG","TW","HK");ts.sort(Comparator.comparingInt(t->{int n=order.indexOf(t.optString("iso_3166_1"));return n<0?9:n;}));}catch(Exception ignored){}
 if(!cjk(d.optString(tk))){String title="";try{JSONObject aliases=fetch(base+"/alternative_titles");JSONArray a=arr(aliases,aliases.has("titles")?"titles":"results");for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i);if(x.optString("iso_3166_1").equals("CN")&&cjk(x.optString("title"))){title=x.getString("title");break;}}}catch(Exception ignored){}if(title.isEmpty())for(JSONObject t:ts){String v=t.getJSONObject("data").optString(tk);if(cjk(v)){title=v;break;}}if(!title.isEmpty())d.put(tk,simplified(title));}
 if(!cjk(d.optString("overview")))for(JSONObject t:ts){String s=t.getJSONObject("data").optString("overview");if(cjk(s)){d.put("overview",simplified(s));break;}}return d;}
 static String genre(int id){int[] ids={28,12,16,35,80,99,18,10751,14,36,27,10402,9648,10749,878,10770,53,10752,37};String[] names={"动作","冒险","动画","喜剧","犯罪","纪录片","剧情","家庭","奇幻","历史","恐怖","音乐","悬疑","爱情","科幻","电视电影","惊悚","战争","西部"};for(int i=0;i<ids.length;i++)if(ids[i]==id)return names[i];return String.valueOf(id);}
 JSONObject preview(JSONObject d,String type)throws Exception{boolean movie=type.equals("movie");String date=d.optString(movie?"release_date":"first_air_date");String title=d.optString(movie?"title":"name");if(title.isEmpty())title=d.optString(movie?"original_title":"original_name");JSONArray gs=new JSONArray(),ids=arr(d,"genre_ids");for(int i=0;i<ids.length();i++)gs.put(genre(ids.getInt(i)));JSONObject m=obj("id","tmdb:"+d.get("id"),"type",type,"name",title,"description",d.optString("overview"),"releaseInfo",date.substring(0,Math.min(4,date.length())),"imdbRating",String.valueOf(d.optDouble("vote_average",0)),"genres",gs,"posterShape","poster");if(!d.isNull("poster_path")&&!d.optString("poster_path").isEmpty())m.put("poster",IMG+"w500"+d.getString("poster_path"));if(!d.isNull("backdrop_path")&&!d.optString("backdrop_path").isEmpty())m.put("background",IMG+"w1280"+d.getString("backdrop_path"));return m;}
 JSONArray genreNames(JSONObject d)throws Exception{JSONArray a=arr(d,"genres"),gs=new JSONArray();for(int i=0;i<a.length();i++)gs.put(a.getJSONObject(i).getString("name"));return gs;}
 String imdb(JSONObject d){JSONObject ex=d.optJSONObject("external_ids");String s=d.optString("imdb_id","");return s.isEmpty()&&ex!=null?ex.optString("imdb_id",""):s;}
 JSONObject translate(JSONObject original,String type){try{String mid=original.optString("id",original.optString("imdb_id"));String media=type.equals("movie")?"movie":"tv";JSONObject d=null;if(original.has("moviedb_id"))try{d=fetch(media+"/"+original.get("moviedb_id"),obj("append_to_response","external_ids"));}catch(Exception ignored){}if(d==null||!imdb(d).equals(mid)){JSONArray found=arr(fetch("find/"+mid,obj("external_source","imdb_id")),type.equals("movie")?"movie_results":"tv_results");if(found.length()==0)return original;d=fetch(media+"/"+found.getJSONObject(0).get("id"),obj("append_to_response","external_ids"));if(!imdb(d).isEmpty()&&!imdb(d).equals(mid))return original;}d=chinese(d,media);JSONObject translated=preview(d,type);translated.put("id",mid).put("imdb_id",mid).put("imdbId",mid).put("tmdbId",d.get("id")).put("genres",genreNames(d));if(translated.optString("description").isEmpty())translated.put("description",original.optString("description"));JSONObject out=copy(original);out.remove("logo");out.remove("slug");out.remove("links");Iterator<String> it=translated.keys();while(it.hasNext()){String k=it.next();out.put(k,translated.get(k));}return out;}catch(Exception e){return original;}}
 JSONObject catalog(String cid,String type,int skip)throws Exception{JSONObject s=specs.get(cid);if(s==null||!s.getString("type").equals(type))throw new IllegalArgumentException("Unknown catalog/type");JSONArray result=new JSONArray();if(s.optString("adapter").equals("localized-platform")){JSONArray all=arr(cached(s.getString("upstream_url"),21600000L),"metas");int start=s.optInt("skip_offset",0)+skip;List<Future<JSONObject>> futures=new ArrayList<>();for(int i=start;i<Math.min(start+20,all.length());i++){JSONObject original=all.getJSONObject(i);futures.add(translations.submit(()->translate(original,type)));}for(Future<JSONObject> f:futures)result.put(f.get());}else{JSONObject p=copy(s.getJSONObject("query"));p.put("page",String.valueOf(s.optInt("page",1)+skip/20));p.put("include_adult","false");JSONArray all=arr(fetch("discover/"+(type.equals("movie")?"movie":"tv"),p),"results");for(int i=0;i<all.length();i++)result.put(preview(all.getJSONObject(i),type));}Log.i("TVCatalog","catalog "+cid+" items="+result.length());return obj("metas",result);}
 JSONObject meta(String type,String requested)throws Exception{String mid=requested,media=type.equals("movie")?"movie":"tv";if(mid.matches("tt\\d+")){JSONArray found=arr(fetch("find/"+mid,obj("external_source","imdb_id")),type.equals("movie")?"movie_results":"tv_results");if(found.length()==0)throw new IllegalArgumentException("Metadata unavailable");mid="tmdb:"+found.getJSONObject(0).get("id");}if(!mid.matches("tmdb:\\d+"))throw new IllegalArgumentException("Unsupported id");String path=media+"/"+mid.substring(5);JSONObject d=chinese(fetch(path,obj("append_to_response","external_ids,credits")),media),m=preview(d,type);m.put("id",requested).put("genres",genreNames(d)).put("runtime",d.optInt("runtime",0)+" min");JSONObject credits=d.optJSONObject("credits");JSONArray cast=new JSONArray(),directors=new JSONArray();if(credits!=null){JSONArray a=arr(credits,"cast"),crew=arr(credits,"crew");for(int i=0;i<Math.min(12,a.length());i++)cast.put(a.getJSONObject(i).optString("name"));for(int i=0;i<crew.length();i++){JSONObject x=crew.getJSONObject(i);if(x.optString("job").equals("Director"))directors.put(x.optString("name"));}}m.put("cast",cast).put("director",directors);String im=imdb(d);if(!im.isEmpty())m.put("imdb_id",im).put("imdbId",im).put("links",new JSONArray().put(obj("name","IMDb","category","imdb","url","https://www.imdb.com/title/"+im)));
 if(type.equals("series")){JSONArray videos=new JSONArray(),seasons=arr(d,"seasons");for(int i=0;i<seasons.length();i++){int sn=seasons.getJSONObject(i).optInt("season_number");if(sn<=0)continue;JSONArray eps=arr(fetch(path+"/season/"+sn),"episodes");for(int j=0;j<eps.length();j++){JSONObject e=eps.getJSONObject(j);videos.put(obj("id",(im.isEmpty()?mid:im)+":"+e.getInt("season_number")+":"+e.getInt("episode_number"),"title",e.optString("name"),"season",e.getInt("season_number"),"episode",e.getInt("episode_number"),"released",e.optString("air_date")+"T00:00:00.000Z"));}}m.put("videos",videos);}return obj("meta",m);}
 JSONObject manifest()throws Exception{JSONArray cats=new JSONArray();for(int i=0;i<config.length();i++){JSONObject s=config.getJSONObject(i);cats.put(obj("id",s.getString("id"),"type",s.getString("type"),"name",s.getString("title"),"extra",new JSONArray().put(obj("name","skip","isRequired",false))));}return obj("id",ADDON,"version","1.3.0","name","中文精选目录（电视本机）","description","目录与封面运行在电视，无需 Mac；按真实地区、类型和制片厂筛选。","resources",new JSONArray().put("catalog").put(obj("name","meta","types",new JSONArray().put("movie").put("series"),"idPrefixes",new JSONArray().put("tmdb:").put("tt"))),"types",new JSONArray().put("movie").put("series"),"catalogs",cats,"behaviorHints",obj("configurable",false));}
 JSONObject artworkItem(String cid)throws Exception{JSONObject s=specs.get(cid);if(s==null)throw new IllegalArgumentException("Unknown art catalog");JSONArray all=catalog(cid,s.getString("type"),0).getJSONArray("metas");List<JSONObject> choices=new ArrayList<>();for(int i=0;i<all.length();i++){JSONObject m=all.getJSONObject(i);if(m.has("background")||m.has("poster"))choices.add(m);}if(choices.isEmpty())throw new IOException("Artwork unavailable");synchronized(artItems){long bucket=System.currentTimeMillis()/8000;JSONObject old=artItems.get(cid);if(old!=null&&Objects.equals(artTimes.get(cid),bucket))return old;if(old!=null&&choices.size()>1)choices.removeIf(m->m.optString("id").equals(old.optString("id")));JSONObject chosen=choices.get(new Random().nextInt(choices.size()));artItems.put(cid,chosen);artTimes.put(cid,bucket);return chosen;}}
 byte[] artwork(JSONObject item)throws Exception{String url=item.optString("background",item.optString("poster"));if(!url.startsWith(IMG))throw new IOException("Invalid artwork");File f=new File(cache,"art-"+hash(url)+".jpg");if(!f.exists())atomic(f,download(url));return Files.readAllBytes(f.toPath());}
 public void run()throws Exception{listener=new ServerSocket();listener.setReuseAddress(true);listener.bind(new InetSocketAddress(InetAddress.getByName("127.0.0.1"),17863),128);Log.i("TVCatalog","Listening on 127.0.0.1:17863 catalogs="+config.length());while(running){Socket s=listener.accept();requests.execute(()->handle(s));}}
 void reply(OutputStream out,int status,byte[] data,String mime,String cacheControl,boolean head,String extra)throws Exception{String h="HTTP/1.1 "+status+(status==200?" OK":status==204?" No Content":" Error")+"\r\nContent-Type: "+mime+"\r\nContent-Length: "+data.length+"\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: GET, HEAD, OPTIONS\r\nAccess-Control-Allow-Headers: *\r\nCache-Control: "+cacheControl+"\r\nConnection: close\r\n"+extra+"\r\n";out.write(h.getBytes(StandardCharsets.UTF_8));if(!head)out.write(data);out.flush();}
 void handle(Socket s){try(Socket socket=s){socket.setSoTimeout(120000);BufferedReader reader=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.UTF_8));String first=reader.readLine();if(first==null)return;String line;int total=first.length();while((line=reader.readLine())!=null&&!line.isEmpty()){total+=line.length();if(total>16384)return;}String[] request=first.split(" ");if(request.length<2)return;boolean head=request[0].equals("HEAD");OutputStream out=socket.getOutputStream();try{if(request[0].equals("OPTIONS")){reply(out,204,new byte[0],"text/plain","no-cache",true,"");return;}if(!request[0].equals("GET")&&!head){reply(out,405,new byte[0],"text/plain","no-cache",true,"");return;}String target=request[1];int qi=target.indexOf('?');String query=qi<0?"":target.substring(qi+1);String path=URLDecoder.decode(qi<0?target:target.substring(0,qi),"UTF-8").replaceAll("^/+|/+$","");byte[] bytes;String mime="application/json; charset=utf-8",cc="no-cache",extra="";
 if(path.equals("health"))bytes=obj("status","ok","addon",ADDON,"catalogs",config.length(),"listen","127.0.0.1:17863","host","Android TV","macRequired",false).toString().getBytes(StandardCharsets.UTF_8);
 else if(path.equals("manifest.json"))bytes=manifest().toString().getBytes(StandardCharsets.UTF_8);
 else if(path.startsWith("catalog/")){String[] p=path.replaceFirst("\\.json$","").split("/",4);int skip=0;String extras=query+(p.length>3?"&"+p[3]:"");for(String pair:extras.split("&"))if(pair.startsWith("skip="))skip=Integer.parseInt(pair.substring(5));if(skip<0)throw new IllegalArgumentException("Invalid skip");bytes=catalog(p[2],p[1],skip).toString().getBytes(StandardCharsets.UTF_8);cc="public, max-age=300";}
 else if(path.startsWith("meta/")){String[] p=path.replaceFirst("\\.json$","").split("/",3);bytes=meta(p[1],p[2]).toString().getBytes(StandardCharsets.UTF_8);cc="public, max-age=300";}
 else if(path.startsWith("art/")){JSONObject m=artworkItem(path.substring(4).replaceFirst("\\.jpg$",""));bytes=artwork(m);mime="image/jpeg";cc="no-store, max-age=0";extra="X-Source-Movie: "+m.getString("id")+"\r\n";}
 else if(path.startsWith("assets/")){String name=path.substring(7);if(!name.matches("[A-Za-z0-9._-]+\\.(png|jpg|jpeg|webp)"))throw new FileNotFoundException();try(InputStream in=ctx.getAssets().open("artwork/"+name);ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] buf=new byte[16384];int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);bytes=b.toByteArray();}mime=name.endsWith(".png")?"image/png":name.endsWith(".webp")?"image/webp":"image/jpeg";cc="public, max-age=3600";}
 else{reply(out,404,"{}".getBytes(),mime,cc,head,"");return;}reply(out,200,bytes,mime,cc,head,extra);
 }catch(Exception e){Log.w("TVCatalog","Request failed "+request[1].split("\\?")[0]+" "+e.getClass().getSimpleName());reply(out,e instanceof FileNotFoundException?404:502,"{\"error\":\"Catalog request failed; retry later\"}".getBytes(StandardCharsets.UTF_8),"application/json","no-cache",head,"");}}
 catch(Exception ignored){} }
 public void close(){running=false;try{listener.close();}catch(Exception ignored){}requests.shutdownNow();translations.shutdownNow();}
}
